#!/usr/bin/env node

/**
 * Post-generation pipeline for openapi-ts.
 *
 * 1. Copy tsconfig.api.json → src/api/tsconfig.json
 * 2. Generate src/services/url-map.ts (function name → URL mapping)
 * 3. Generate src/services/service-registry.gen.ts (type-safe domain service map)
 * 4. Format generated files with Biome
 */

import { copyFileSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { execFileSync } from 'node:child_process'

// Step 1: Copy tsconfig
const tsconfigSrc = resolve('tsconfig.api.json')
const tsconfigDest = resolve('src/api/tsconfig.json')
copyFileSync(tsconfigSrc, tsconfigDest)
console.log('Copied tsconfig.api.json → src/api/tsconfig.json')

// Step 2 & 3: Parse sdk.gen.ts (shared between url-map and service-types)
const sdkPath = resolve('src/api/sdk.gen.ts')
const content = readFileSync(sdkPath, 'utf-8')

const fnPattern = /export const (\w+)/
const urlPattern = /url: '([^']+)'/

const lines = content.split('\n')
const entries = []
let currentFn = null

for (const line of lines) {
  const fnMatch = fnPattern.exec(line)
  if (fnMatch) {
    currentFn = fnMatch[1]
    const urlMatch = urlPattern.exec(line)
    if (urlMatch) {
      entries.push([currentFn, urlMatch[1]])
      currentFn = null
    }
  } else if (currentFn) {
    const urlMatch = urlPattern.exec(line)
    if (urlMatch) {
      entries.push([currentFn, urlMatch[1]])
      currentFn = null
    }
  }
}

// Step 2: Generate url-map.ts
const urlMapPath = resolve('src/services/url-map.ts')
const mapEntries = entries.map(([fn, url]) => `  ['${fn}', '${url}'],`).join('\n')
writeFileSync(
  urlMapPath,
  `export const SDK_URL_MAP = new Map<string, string>([\n${mapEntries}\n])\n`,
  'utf-8'
)
console.log(`Generated ${entries.length} entries in src/services/url-map.ts`)

// Step 3: Generate service-registry.gen.ts
function extractDomain(fnName, url) {
  if (url.startsWith('/fdb-hub')) return 'fdbHub'

  const match = /^\/video-hub\/api\/v1\/([^/]+)/.exec(url)
  if (match?.[1]) {
    return match[1].replace(/_([a-z])/g, (_, c) => c.toUpperCase())
  }

  return fnName
}

function simplifyMethodName(fnName) {
  const cleaned = fnName.replace(/(Get|Post)$/, '')
  const match = /^(.+?)ApiV1/.exec(cleaned)
  return match?.[1] ?? cleaned
}

const domains = {}
for (const [fnName, url] of entries) {
  const domain = extractDomain(fnName, url)
  const methodName = simplifyMethodName(fnName)

  domains[domain] ??= new Map()
  domains[domain].set(methodName, fnName)
}

const sortedDomains = Object.keys(domains).sort()

const domainEntries = sortedDomains
  .map((domain) => {
    const methods = [...domains[domain].entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([methodName, fnName]) => `    readonly ${methodName}: typeof sdk.${fnName}`)
      .join('\n')
    return `  readonly ${domain}: {\n${methods}\n  }`
  })
  .join('\n')

const registryPath = resolve('src/services/service-registry.gen.ts')
writeFileSync(
  registryPath,
  `// This file is auto-generated by scripts/post-generate.js\n// Do not edit manually.\n\nimport type * as sdk from '../api/sdk.gen.js'\n\nexport interface DomainServiceMap {\n${domainEntries}\n}\n\nexport type DomainName = keyof DomainServiceMap\n`,
  'utf-8'
)

const totalMethods = Object.values(domains).reduce((sum, m) => sum + m.size, 0)
console.log(
  `Generated ${sortedDomains.length} domains with ${totalMethods} methods in src/services/service-registry.gen.ts`
)

// Step 4: Format generated files with Biome
// Using execFileSync (not exec) — no shell injection risk, all args are hardcoded paths
const biomeBin = resolve('node_modules/.bin', process.platform === 'win32' ? 'biome.cmd' : 'biome')
execFileSync(biomeBin, ['format', '--write', urlMapPath, registryPath], { stdio: 'inherit' })
console.log('Formatted generated files')
